preConditionHook:
// EL's Percentile(pct, series, N) per the VERIFIED register row
// (EL_Percentile_Probe.txt / el_percentile_output.txt): copy the window of
// bars 0..N-1 -- current bar INCLUDED -- sort it and linearly interpolate
// at rank = pct*(N-1) between the two adjacent sorted values (Excel
// PERCENTILE.INC; duplicates are interpolated across, {2,2,4,4} median = 3).
// pct is a 0..1 FRACTION; out of range returns EL's -1 sentinel (measured
// at pct = 25). The window is the close SERIES, which has real
// pre-first-bar history, so no zero-fill mirror is needed. Interpolation
// temporaries live in block scope; everything at hook scope is a declared
// local so it takes the placement prefix (the AdxBelowThreshold
// unprefixed-temporaries lesson).
// Both percentile values are computed every bar, exactly as the EL twin's
// two Percentile calls are -- one sort serves both, since Percentile is a
// pure function of the same window.
cpvSorted.assign((std::size_t)(int)lookback, 0.0);
for (int i = 0; i < (int)lookback; ++i) cpvSorted[(std::size_t)i] = close[i];
// Insertion sort, ascending, in plain loops -- the only non-EL construct is
// the buffer itself (the AtrRising std::vector precedent). The comparisons
// inside the sort are between tick-grid closes, where the EL tolerance
// cannot bind (differences are 0 or >= 1 tick).
for (int i = 1; i < (int)lookback; ++i) {
    double key = cpvSorted[(std::size_t)i];
    int j = i - 1;
    while (j >= 0 && cpvSorted[(std::size_t)j] > key) {
        cpvSorted[(std::size_t)(j + 1)] = cpvSorted[(std::size_t)j];
        j = j - 1;
    }
    cpvSorted[(std::size_t)(j + 1)] = key;
}
cpvHigh = 0.0;
if (percentileHigh < 0.0 || percentileHigh > 1.0) {
    cpvHigh = -1.0;
} else {
    double rank = percentileHigh * ((int)lookback - 1);
    int lo = (int)rank;
    double frac = rank - lo;
    cpvHigh = cpvSorted[(std::size_t)lo];
    if (frac > 0.0) cpvHigh = cpvHigh + frac * (cpvSorted[(std::size_t)(lo + 1)] - cpvSorted[(std::size_t)lo]);
}
cpvLow = 0.0;
if (percentileLow < 0.0 || percentileLow > 1.0) {
    cpvLow = -1.0;
} else {
    double rank = percentileLow * ((int)lookback - 1);
    int lo = (int)rank;
    double frac = rank - lo;
    cpvLow = cpvSorted[(std::size_t)lo];
    if (frac > 0.0) cpvLow = cpvLow + frac * (cpvSorted[(std::size_t)(lo + 1)] - cpvSorted[(std::size_t)lo]);
}
